import { headers } from 'next/headers';

type UserPreferences = {
  theme: string;
  language: string;
  emailNotifications: boolean;
};

const defaultPreferences: UserPreferences = {
  theme: 'system',
  language: 'en',
  emailNotifications: true
};

async function getUserPreferences(): Promise<UserPreferences> {
  const requestHeaders = await headers();
  const host = requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host');
  const protocol = requestHeaders.get('x-forwarded-proto') ?? 'http';
  const cookie = requestHeaders.get('cookie');

  if (!host) {
    return defaultPreferences;
  }

  try {
    const res = await fetch(, {
      cache: 'no-store',
      headers: cookie ? { cookie } : undefined
    });

    if (!res.ok) {
      return defaultPreferences;
    }

    const preferences = (await res.json()) as Partial<UserPreferences>;

    return {
      theme: typeof preferences.theme === 'string' ? preferences.theme : defaultPreferences.theme,
      language:
        typeof preferences.language === 'string' ? preferences.language : defaultPreferences.language,
      emailNotifications:
        typeof preferences.emailNotifications === 'boolean'
          ? preferences.emailNotifications
          : defaultPreferences.emailNotifications
    };
  } catch {
    return defaultPreferences;
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Theme: {preferences.theme}</p>
      <p>Language: {preferences.language}</p>
      <p>Email notifications: {preferences.emailNotifications ? 'Enabled' : 'Disabled'}</p>
    </div>
  );
}

